begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('f0000000-0000-4000-8000-000000005561','economic-ai-owner@example.test',now()),
 ('f0000000-0000-4000-8000-000000005562','economic-ai-staff@example.test',now());
insert into platform_hosts(user_id) values('f0000000-0000-4000-8000-000000005561');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000005561","role":"authenticated"}';
select set_ai_platform_settings('{"enabled":true,"monthlyCapOre":100000,"includedOre":600,"packOre":10000,"reserveOre":50,"reserveBatchOre":200}');
select set_config('test.ea',create_tenant_with_locale('Economic AI','economic-ai',gen_random_uuid(),'dk')::text,true);
select store_economic_connection(current_setting('test.ea')::uuid,123456,'Synthetic','','DKK','{"iv":"aWl2","tag":"dGFn","data":"ZGF0YQ=="}');
select set_config('test.rev',read_economic_connection(current_setting('test.ea')::uuid)->>'revision',true);
select set_config('test.req',gen_random_uuid()::text,true);
select set_config('test.accounts','[{"account":"10000","name":"Synthetic bank","type":"status"},{"account":"30000","name":"Synthetic sales","type":"profitAndLoss"}]',true);
select is(begin_economic_accounting_assistance(current_setting('test.ea')::uuid,current_setting('test.req')::uuid,null,'dk','fixture',123456,current_setting('test.rev')::uuid,current_setting('test.accounts')::jsonb)->>'reserved','true','economic generation reserves');
select is(begin_economic_accounting_assistance(current_setting('test.ea')::uuid,current_setting('test.req')::uuid,null,'dk','fixture',123456,current_setting('test.rev')::uuid,current_setting('test.accounts')::jsonb)->>'reserved','false','same attempt reserves only once');
select is((select count(*) from usage_events where tenant_id=current_setting('test.ea')::uuid and feature='reception_assistance'),1::bigint,'shared quota is charged once');
select is((select count(*) from ai_credit_events where reference='attempt:'||current_setting('test.req') and kind='reserved'),1::bigint,'economic retry reserves AI credits once');
select throws_ok($$select begin_economic_accounting_assistance(current_setting('test.ea')::uuid,gen_random_uuid(),null,'dk','fixture',123456,current_setting('test.rev')::uuid,current_setting('test.accounts')::jsonb)$$,'P0001','ASSISTANCE_LIMIT','economic assistance shares cooldown');
select throws_ok($$select begin_accounting_assistance(current_setting('test.ea')::uuid,current_setting('test.req')::uuid,null,'dk','fixture')$$,'P0001','REQUEST_CONFLICT','economic attempt cannot be replayed as BAS');
select throws_ok($$select complete_accounting_assistance(current_setting('test.ea')::uuid,current_setting('test.req')::uuid,'{"rows":[{"key":"grossOre","account":"1930","side":"debit","reason":"Not in catalogue"}],"warnings":[]}',1,1)$$,'P0001','INVALID_INPUT','BAS account outside actual catalogue is rejected');
select throws_ok($$select complete_accounting_assistance(current_setting('test.ea')::uuid,current_setting('test.req')::uuid,'{"rows":[{"key":"grossOre","account":"10000","side":"debit","vatCode":"Z0","reason":"Forbidden VAT choice"}],"warnings":[]}',1,1)$$,'P0001','INVALID_INPUT','AI cannot choose a VAT code');
select complete_accounting_assistance(current_setting('test.ea')::uuid,current_setting('test.req')::uuid,'{"rows":[{"key":"grossOre","account":"10000","side":"debit","reason":"Review clearing"}],"warnings":[]}',100,50);
select is((select payload->>'destination' from pending_operations where id=current_setting('test.req')::uuid),'economic','pending draft routes to economic editor');
select decide_operation(current_setting('test.ea')::uuid,gen_random_uuid(),current_setting('test.req')::uuid,'approved','');
select is((select outcome from operation_decisions where operation_id=current_setting('test.req')::uuid),'executed','owner can use draft in editor');
select is((select count(*) from economic_maps where tenant_id=current_setting('test.ea')::uuid),0::bigint,'using draft never publishes map');
select is((select count(*) from economic_exports where tenant_id=current_setting('test.ea')::uuid),0::bigint,'using draft never exports');
select set_config('test.eb',create_tenant_with_locale('Economic AI stale','economic-ai-stale',gen_random_uuid(),'dk')::text,true);
select store_economic_connection(current_setting('test.eb')::uuid,123456,'Synthetic','','DKK','{"iv":"aWl2","tag":"dGFn","data":"ZGF0YQ=="}');
select set_config('test.stale',gen_random_uuid()::text,true);
select begin_economic_accounting_assistance(current_setting('test.eb')::uuid,current_setting('test.stale')::uuid,null,'dk','fixture',123456,(read_economic_connection(current_setting('test.eb')::uuid)->>'revision')::uuid,current_setting('test.accounts')::jsonb);
select complete_accounting_assistance(current_setting('test.eb')::uuid,current_setting('test.stale')::uuid,'{"rows":[],"warnings":["Review"]}',100,10);
select store_economic_connection(current_setting('test.eb')::uuid,123456,'Synthetic','','DKK','{"iv":"aWl2","tag":"dGFn","data":"ZGF0YQ=="}');
select decide_operation(current_setting('test.eb')::uuid,gen_random_uuid(),current_setting('test.stale')::uuid,'approved','');
select is((select outcome from operation_decisions where operation_id=current_setting('test.stale')::uuid),'failed','changed connection prevents using stale draft');
select set_config('test.ec',create_tenant_with_locale('Economic AI preserve','economic-ai-preserve',gen_random_uuid(),'dk')::text,true);
select store_economic_connection(current_setting('test.ec')::uuid,123456,'Synthetic','','DKK','{"iv":"aWl2","tag":"dGFn","data":"ZGF0YQ=="}');
select set_config('test.map',publish_economic_map(current_setting('test.ec')::uuid,gen_random_uuid(),null,123456,1,'{"grossOre":{"account":"10000","side":"debit","vatCode":"Z0"},"commissionOre":{"excludeReason":"Already posted"}}')::text,true);
select set_config('test.preserve',gen_random_uuid()::text,true);
select begin_economic_accounting_assistance(current_setting('test.ec')::uuid,current_setting('test.preserve')::uuid,current_setting('test.map')::uuid,'dk','fixture',123456,(read_economic_connection(current_setting('test.ec')::uuid)->>'revision')::uuid,current_setting('test.accounts')::jsonb);
select throws_ok($$select complete_accounting_assistance(current_setting('test.ec')::uuid,current_setting('test.preserve')::uuid,'{"rows":[{"key":"grossOre","account":"30000","side":"credit","reason":"Overwrite"}],"warnings":[]}',1,1)$$,'P0001','INVALID_INPUT','existing economic account cannot be overwritten');
select throws_ok($$select complete_accounting_assistance(current_setting('test.ec')::uuid,current_setting('test.preserve')::uuid,'{"rows":[{"key":"commissionOre","account":"30000","side":"credit","reason":"Overwrite"}],"warnings":[]}',1,1)$$,'P0001','INVALID_INPUT','explicit exclusion cannot be overwritten');
select complete_accounting_assistance(current_setting('test.ec')::uuid,current_setting('test.preserve')::uuid,'{"rows":[],"warnings":["Review"]}',100,10);
select publish_economic_map(current_setting('test.ec')::uuid,gen_random_uuid(),current_setting('test.map')::uuid,123456,1,'{"grossOre":{"account":"10000","side":"debit","vatCode":"Z0"}}');
select decide_operation(current_setting('test.ec')::uuid,gen_random_uuid(),current_setting('test.preserve')::uuid,'approved','');
select is((select outcome from operation_decisions where operation_id=current_setting('test.preserve')::uuid),'failed','concurrent map publication prevents use');
reset role;
insert into tenant_members(tenant_id,user_id,role) values(current_setting('test.ea')::uuid,'f0000000-0000-4000-8000-000000005562','staff');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000005562","role":"authenticated"}';
select throws_ok($$select begin_economic_accounting_assistance(current_setting('test.ea')::uuid,gen_random_uuid(),null,'dk','fixture',123456,current_setting('test.rev')::uuid,current_setting('test.accounts')::jsonb)$$,'P0001','FORBIDDEN','staff cannot generate drafts');
select is((select count(*) from accounting_ai_attempts),0::bigint,'staff cannot read drafts');
select * from finish();
rollback;
